import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { corpusRoot, routeOf } from "./translations.mjs";

// The Examples section of the sidebar, read from the corpus while the site is
// configured, so no list of examples is kept here.
//
// The teaching order has one source: the "In teaching order" section of
// language-reference/examples/by-product-and-capability.md. That page is
// generated by scripts/gen-examples-index.sh, which alone reads the header of
// each example's README and the tier list in the examples README, and its
// --check mode refuses a page that is not current with them. In the section,
// each tier is a level-three heading carrying its title, followed by one line
// per example, `- [name](name/README.md) …`, in the order to work through them.
// This module reads those headings and those entry lines, and nothing else: no
// header, no tier list. The command `aggrega draft --example --list` reads
// the page too, with a reader of its own, and nothing here checks that the two
// readings agree. A section holding no entry line this module recognizes stops
// the build, naming the page, rather than publishing a sidebar with no example.
//
// The section lists, in order: the folder's overview (its README.md), the page
// listing the examples by product and capability, and the page on reading the
// output the examples print; then one group per tier holding an example,
// labelled with the tier's title, the first open and the others collapsed; then
// "Concepts", every other page of the folder, in file name order. Each example
// is listed under its page's title, which Starlight reads from the page in each
// language.
//
// A version whose index page carries no teaching-order section is listed as
// Starlight lists a directory, by file path.

const EXAMPLES = "language-reference/examples";
const OVERVIEW = "README.md";
const INDEX = "by-product-and-capability.md";
// The pages about the examples as a whole, listed after the overview rather than
// with the concept pages.
const ABOUT_THE_EXAMPLES = [INDEX, "reading-the-output.md"];
const TEACHING_ORDER = "## In teaching order";

// The tiers of the index page's teaching-order section, each { title, names },
// in the order the page gives them; undefined when the page holds no such
// section. The section ends at the next level-two heading.
function teachingOrder(markdown) {
  const lines = markdown.split(/\r?\n/);
  const start = lines.indexOf(TEACHING_ORDER);
  if (start < 0) return undefined;
  const tiers = [];
  for (const line of lines.slice(start + 1)) {
    if (/^## /.test(line)) break;
    const heading = line.match(/^### (.+?)\s*$/);
    if (heading) {
      tiers.push({ title: heading[1], names: [] });
      continue;
    }
    const entry = line.match(/^- \[([^\]]+)\]\(\1\/README\.md\)/);
    if (entry && tiers.length > 0) tiers[tiers.length - 1].names.push(entry[1]);
  }
  return tiers;
}

/**
 * The items of the sidebar's Examples group, for the corpus at `root`.
 * `autogenerate` is the entry listing the folder by file path, used for a
 * version whose index page carries no teaching-order section.
 */
export function examplesSidebarItems(autogenerate, root = corpusRoot) {
  const folder = path.join(root, EXAMPLES);
  const indexFile = path.join(folder, INDEX);
  const tiers = existsSync(indexFile) ? teachingOrder(readFileSync(indexFile, "utf-8")) : undefined;
  if (!tiers) return [autogenerate];
  if (!tiers.some(({ names }) => names.length > 0)) {
    throw new Error(
      `${EXAMPLES}/${INDEX}: its "${TEACHING_ORDER.slice(3)}" section holds no example entry of the form ` +
        "- [name](name/README.md), so the sidebar would list no example; run scripts/gen-examples-index.sh " +
        "in this repository to write the page again.",
    );
  }

  // Each page is named by its route, by the rule the content collection names
  // its entries with (routeOf); an English path is the same in every corpus.
  const pages = readdirSync(folder, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith(".md"))
    .map((entry) => entry.name)
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const about = ABOUT_THE_EXAMPLES.filter((file) => pages.includes(file));
  const concepts = pages.filter((file) => file !== OVERVIEW && !ABOUT_THE_EXAMPLES.includes(file));

  return [
    routeOf(`${EXAMPLES}/${OVERVIEW}`),
    ...about.map((file) => routeOf(`${EXAMPLES}/${file}`)),
    ...tiers
      .filter(({ names }) => names.length > 0)
      .map(({ title, names }, index) => ({
        label: title,
        collapsed: index > 0,
        items: names.map((name) => routeOf(`${EXAMPLES}/${name}/README.md`)),
      })),
    ...(concepts.length > 0
      ? [{ label: "Concepts", collapsed: true, items: concepts.map((file) => routeOf(`${EXAMPLES}/${file}`)) }]
      : []),
  ];
}
